import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-B8n3BMtg.js";import{t as n}from"./google-drive-B09t_-TV.js";import{t as r}from"./slack-DM74pMYS.js";import{t as i}from"./gmail-CrQFJd-l.js";import{t as a}from"./google-calendar-Bq7K_MpA.js";var o=t({slug:`slack`,connectorName:`Slack`,heroLogo:r,heroTitle:e({defaultMessage:`Connect your Slack to Perplexity`,id:`bc3099066c`}),heroSubtitle:e({defaultMessage:`Search and post messages across your Slack workspace. Answers are grounded in the DMs, private channels, and public channels you have access to.`,id:`efdbc6224f`}),primaryCta:e({defaultMessage:`Connect Slack`,id:`b6addebe9b`}),primaryCtaUrl:`/computer/connectors?connector=slack_direct`,heroPromptText:e({defaultMessage:`Summarize this week's discussions in #product-launch and post a comprehensive recap to the #leadership Slack channel`,id:`612adba639`}),waysToUseSectionTitle:e({defaultMessage:`Ways to use Slack and Perplexity`,id:`bf42e9cfa4`}),waysToUseValueProps:[e({defaultMessage:`Search messages across DMs, private channels, and public channels you have access to in Slack`,id:`af29c59930`}),e({defaultMessage:`Post messages directly to Slack`,id:`788503b64e`}),e({defaultMessage:`Data is retrieved from and written back to Slack whenever you run a query in Perplexity`,id:`3274fc1bbb`})],documentation:{enabled:!0,oauthScopes:[{scope:`Search Slack users`,type:`Read`,justification:e({defaultMessage:`Searches for Slack users by name, email, or profile attributes such as department, role, or title. Returns matching user records including user IDs.`,id:`cc046e4fae`})},{scope:`Search all Slack channels`,type:`Read`,justification:e({defaultMessage:`Searches messages and files across all Slack channels including private channels, DMs, and group DMs. Requires user consent before use. Supports the same keyword/natural-language query modifiers as the public search.`,id:`e0d7a4e63b`})},{scope:`Search public Slack channels`,type:`Read`,justification:e({defaultMessage:`Searches messages and files in public Slack channels using keywords or natural language, with support for modifiers like in:, from:, before:/after:, and content-type filters. Does not search private channels or DMs.`,id:`7e8c937008`})},{scope:`Search Slack channels`,type:`Read`,justification:e({defaultMessage:`Searches for Slack channels by name or description. Returns channel names, IDs, topics, purposes, and archive status.`,id:`3a44ec8290`})},{scope:`Read a Slack user profile`,type:`Read`,justification:e({defaultMessage:`Retrieves detailed profile information for a Slack user, including contact info, status, timezone, organization, and role. Defaults to the current user if no user_id is provided.`,id:`9f61350894`})},{scope:`Read a Slack thread`,type:`Read`,justification:e({defaultMessage:`Reads the parent message and all replies in a specific Slack thread. Requires the channel_id and the parent message's timestamp (message_ts).`,id:`e2f08a36c9`})},{scope:`Read a Slack channel`,type:`Read`,justification:e({defaultMessage:`Reads messages from a Slack channel or DM in reverse chronological order (newest first), given a channel_id or user_id. Use slack_read_thread to retrieve thread replies.`,id:`eeb221d801`})},{scope:`Read a Slack Canvas`,type:`Read`,justification:e({defaultMessage:`Retrieves the markdown content and section ID mapping of an existing Slack Canvas document. Use section IDs returned here to safely target sections in slack_update_canvas.`,id:`4d3ef68863`})},{scope:`Update a Slack Canvas`,type:`Write`,justification:e({defaultMessage:`Appends, prepends, or replaces content in an existing Slack Canvas. Use a section_id (from slack_read_canvas) with action=replace to safely update a specific section without overwriting the entire canvas.`,id:`c5c734b66f`})},{scope:`Create a Slack message draft`,type:`Write`,justification:e({defaultMessage:`Saves a markdown-formatted message as a draft in a Slack channel's Drafts & Sent without sending it. Supports optional thread replies. Returns a link to the channel where the draft was created.`,id:`2c33fa5f36`})},{scope:`Send a Slack message`,type:`Write`,justification:e({defaultMessage:`Sends a markdown-formatted message immediately to a Slack channel or DM (use user_id as channel_id for DMs). Supports thread replies via thread_ts. Returns a link to the sent message.`,id:`6c06bfff97`})},{scope:`Schedule a Slack message`,type:`Write`,justification:e({defaultMessage:`Schedules a markdown-formatted message for future delivery to a Slack channel or DM. Requires a Unix timestamp at least 2 minutes in the future (max 120 days out). Does not send immediately.`,id:`4ff1fc8d13`})},{scope:`Create a Slack Canvas`,type:`Write`,justification:e({defaultMessage:`Creates a new Slack Canvas document from Canvas-flavored Markdown content and returns the canvas link. Not available on free Slack teams.`,id:`966f4014ef`})}],dataAccessCards:[{title:e({defaultMessage:`Protocol`,id:`2ce316f430`}),description:e({defaultMessage:`Slack Web API (HTTPS) + Events API for real-time. All requests authenticated via user-level OAuth token.`,id:`13d76c6cc0`})},{title:e({defaultMessage:`Data Transmission`,id:`3f10a26a7d`}),description:e({defaultMessage:`TLS 1.2+ in transit. No data stored at rest — queries are executed on-demand and results are ephemeral within the session.`,id:`387fddd145`})},{title:e({defaultMessage:`Permission Inheritance`,id:`c61101f845`}),description:e({defaultMessage:`Respects Slack's native permission model — users can only access channels they are a member of. No elevation of privilege.`,id:`ea18e59332`})},{title:e({defaultMessage:`Write Actions`,id:`2f59e18d25`}),description:e({defaultMessage:`All write operations (send_a_slack_message, schedule_a_slack_message, update_a_slack_canvas) require explicit user confirmation before execution. Can be disabled org-wide by admin.`,id:`e337959914`})}],connectorType:{badge:`MCP`,title:e({defaultMessage:`Built on MCP`,id:`7bad7b2ebc`}),description:e({defaultMessage:`An open-standard integration using the Model Context Protocol, so it works consistently across MCP-compatible tools.`,id:`6a49100140`})}},featureSectionTitle:e({defaultMessage:`Used commonly with Slack`,id:`c5e072c2c4`}),featureCards:[{icon:i,title:e({defaultMessage:`Gmail`,id:`1c4f78acdc`}),description:e({defaultMessage:`Search across Slack threads and Gmail in a single query — find a decision whether it happened in a DM or your inbox.`,id:`2aef93e318`})},{icon:n,title:e({defaultMessage:`Google Drive`,id:`e4d51fa24f`}),description:e({defaultMessage:`Pair Slack discussions with the docs, sheets, and decks shared in Drive — pull a thread and the file it references together.`,id:`8a5d69e094`})},{icon:a,title:e({defaultMessage:`Google Calendar`,id:`6935472824`}),description:e({defaultMessage:`Tie Slack messages to the meetings on your calendar — see what was decided before, during, and after each event.`,id:`e444634674`})}],exampleQueriesSectionTitle:e({defaultMessage:`Ask anything, get the full picture`,id:`cbed038ec5`}),exampleQueries:[[e({defaultMessage:`What did the design team discuss in #design this week?`,id:`01de5f2280`}),e({defaultMessage:`Find Sarah's last message about the Q2 launch.`,id:`4f59dae7f6`}),e({defaultMessage:`Summarize the #product-launch channel from yesterday.`,id:`a7a3a377e6`}),e({defaultMessage:`Pull all Loom links shared in #engineering last month.`,id:`c6da5cb37e`}),e({defaultMessage:`Who mentioned the customer churn analysis in DMs?`,id:`8260e72f18`}),e({defaultMessage:`What decisions were made in #leadership this week?`,id:`6aaa212ae2`}),e({defaultMessage:`Find every link to the marketing brief shared in Slack.`,id:`53b7f7ab0a`})],[e({defaultMessage:`Show me what was said about the new pricing in #sales.`,id:`e2430aa908`}),e({defaultMessage:`Pull all questions asked in #support today.`,id:`bfc707ef05`}),e({defaultMessage:`Who's been most active in #design-reviews this month?`,id:`1d2ab23487`}),e({defaultMessage:`Summarize the standup notes posted in #eng-standup.`,id:`f9349e7590`}),e({defaultMessage:`Find the figma link Jamie shared two weeks ago.`,id:`7162227e28`}),e({defaultMessage:`What's the consensus from #engineering on the migration plan?`,id:`5eee42026d`}),e({defaultMessage:`Who replied to the launch announcement?`,id:`05a6961e56`})],[e({defaultMessage:`What feedback did customers share in #customer-feedback?`,id:`02b0db42ad`}),e({defaultMessage:`Pull all action items from #ops-weekly this quarter.`,id:`9b4f5def83`}),e({defaultMessage:`Find every doc shared in #marketing last week.`,id:`13cb73e5e1`}),e({defaultMessage:`Summarize the conversation in DMs with the design lead.`,id:`4eb885bce4`}),e({defaultMessage:`What blockers were raised in #engineering yesterday?`,id:`6b517b35f4`}),e({defaultMessage:`Who has reactions on the new roadmap post?`,id:`aa6c0d74de`}),e({defaultMessage:`Find the latest update on Project Atlas in #atlas-team.`,id:`6b2027fbfc`})]],footerTitle:e({defaultMessage:`Connect your workspace to Perplexity`,id:`48eda9979b`})});export{o as default};
